package examine_test

import (
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"os"
	"path/filepath"
	"testing"
)

// The carving fixtures (3E Task 1) are generated by tools/fixtures/carve_gen.sh in a pinned Docker image from
// real encoders; their oracle (the SHA-256 of every object, its tool-reported facts, and where each object sits
// in each image) is read from the finished bytes by tools, never by Minutiae. These tests only prove that the
// committed files are the ones the oracle describes: a regenerated image without its oracle, or the reverse,
// fails here first.

const (
	carveObjectsDir = "../carve/testdata/objects"
	carveImagesDir  = "testdata/carve"
	carveBudget     = 250 << 10 // the size budget of the objects directory and of each .img.gz
)

type carveObjectsExpect struct {
	Objects []struct {
		File   string `json:"file"`
		Family string `json:"family"`
		Type   string `json:"type"`
		Ext    string `json:"ext"`
		Size   int64  `json:"size"`
		SHA256 string `json:"sha256"`
		Expect string `json:"expect"`
	} `json:"objects"`
}

type carveImagesExpect struct {
	Images []struct {
		Name      string             `json:"name"`
		ImageSHA  string             `json:"image_sha256"`
		Size      int64              `json:"size"`
		Table     string             `json:"table"`
		FS        string             `json:"fs"`
		BlockSize int64              `json:"block_size"`
		Objects   []carveImageObject `json:"objects"`
		Controls  []struct {
			Kind        string `json:"kind"`
			ImageOffset int64  `json:"image_offset"`
			Length      int64  `json:"length"`
		} `json:"controls"`
	} `json:"images"`
}

type carveImageObject struct {
	Name        string `json:"name"`
	Family      string `json:"family"`
	Type        string `json:"type"`
	ImageOffset int64  `json:"image_offset"`
	Length      int64  `json:"length"`
	SHA256      string `json:"sha256"`
	State       string `json:"state"`
	Expect      string `json:"expect"`
	NestedIn    *int64 `json:"nested_in"`
}

func carveSum(b []byte) string {
	s := sha256.Sum256(b)
	return hex.EncodeToString(s[:])
}

func TestObjectsFixtureIntact(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join(carveObjectsDir, "objects.expect.json"))
	if err != nil {
		t.Fatalf("the objects oracle is missing: %v", err)
	}
	var exp carveObjectsExpect
	if err := json.Unmarshal(raw, &exp); err != nil {
		t.Fatal(err)
	}
	if len(exp.Objects) == 0 {
		t.Fatal("objects.expect.json lists no object")
	}
	listed := map[string]bool{"objects.expect.json": true}
	var total int64
	for _, o := range exp.Objects {
		listed[o.File] = true
		b, err := os.ReadFile(filepath.Join(carveObjectsDir, o.File))
		if err != nil {
			t.Errorf("%s: %v", o.File, err)
			continue
		}
		total += int64(len(b))
		if int64(len(b)) != o.Size {
			t.Errorf("%s: %d bytes, oracle says %d", o.File, len(b), o.Size)
		}
		if got := carveSum(b); got != o.SHA256 {
			t.Errorf("%s: sha256 %s, oracle says %s", o.File, got, o.SHA256)
		}
		if o.Family == "" || o.Type == "" || o.Ext == "" || o.Expect == "" {
			t.Errorf("%s: incomplete oracle row %+v", o.File, o)
		}
	}
	ents, err := os.ReadDir(carveObjectsDir)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range ents {
		if !listed[e.Name()] {
			t.Errorf("%s is in the objects directory but not in the oracle", e.Name())
		}
	}
	if total > carveBudget {
		t.Errorf("objects directory holds %d bytes, budget %d", total, carveBudget)
	}
}

func TestCarveFixturesIntact(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join(carveImagesDir, "carve.expect.json"))
	if err != nil {
		t.Fatalf("the image oracle is missing: %v", err)
	}
	var exp carveImagesExpect
	if err := json.Unmarshal(raw, &exp); err != nil {
		t.Fatal(err)
	}
	if len(exp.Images) == 0 {
		t.Fatal("carve.expect.json lists no image")
	}
	for _, im := range exp.Images {
		t.Run(im.Name, func(t *testing.T) {
			path := filepath.Join(carveImagesDir, im.Name+".img.gz")
			if info, err := os.Stat(path); err != nil {
				t.Fatal(err)
			} else if info.Size() > carveBudget {
				t.Errorf("%s is %d bytes, budget %d", path, info.Size(), carveBudget)
			}
			gz, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			zr, err := gzip.NewReader(bytes.NewReader(gz))
			if err != nil {
				t.Fatal(err)
			}
			img, err := io.ReadAll(zr)
			if err != nil {
				t.Fatal(err)
			}
			// the image hash first: a mismatch means image and oracle were not regenerated together
			if got := carveSum(img); got != im.ImageSHA {
				t.Fatalf("image sha256 %s, oracle says %s", got, im.ImageSHA)
			}
			if int64(len(img)) != im.Size {
				t.Errorf("image is %d bytes, oracle says %d", len(img), im.Size)
			}
			objs := im.Objects
			if len(objs) == 0 {
				t.Fatal("no object in the oracle")
			}
			for _, o := range objs {
				switch o.State {
				case "deleted", "live", "placed":
				default:
					t.Errorf("%s: unknown state %q", o.Name, o.State)
					continue
				}
				if o.ImageOffset < 0 || o.Length <= 0 || o.ImageOffset+o.Length > int64(len(img)) {
					t.Errorf("%s: range [%d,+%d) outside the %d-byte image", o.Name, o.ImageOffset, o.Length, len(img))
					continue
				}
				if got := carveSum(img[o.ImageOffset : o.ImageOffset+o.Length]); got != o.SHA256 {
					t.Errorf("%s: bytes at %d hash %s, oracle says %s", o.Name, o.ImageOffset, got, o.SHA256)
				}
			}
			for _, c := range im.Controls {
				if c.ImageOffset < 0 || c.Length <= 0 || c.ImageOffset+c.Length > int64(len(img)) {
					t.Errorf("control %s: range [%d,+%d) outside the image", c.Kind, c.ImageOffset, c.Length)
				}
			}
		})
	}
}
